package com.quinn.hboot.family.service;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.quinn.hboot.common.exception.BusinessException;
import com.quinn.hboot.family.mapper.*;
import com.quinn.hboot.family.model.dto.FamilyRequests;
import com.quinn.hboot.family.model.entity.*;
import com.quinn.hboot.photo.mapper.PhotoMediaMapper;
import com.quinn.hboot.photo.model.entity.PhotoMedia;
import com.quinn.hboot.photo.model.entity.PhotoSpace; import com.quinn.hboot.photo.model.entity.PhotoSpaceMember; import com.quinn.hboot.photo.mapper.PhotoSpaceMemberMapper;
import com.quinn.hboot.photo.service.PhotoAlbumService;
import com.quinn.hboot.knowledge.support.KnowledgeDocumentExtractor;
import com.quinn.hboot.system.mapper.FileMapper;
import com.quinn.hboot.system.model.entity.SysFile;
import com.quinn.hboot.system.service.FileService;
import com.quinn.hboot.utils.SecurityUtils;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;
import org.springframework.web.multipart.MultipartFile;
import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;

@Service @RequiredArgsConstructor @Transactional
public class FamilyAssetService {
  private final PhotoAlbumService photoService; private final PhotoMediaMapper mediaMapper; private final PhotoSpaceMemberMapper memberMapper; private final FileMapper fileMapper; private final FileService fileService; private final KnowledgeDocumentExtractor extractor;
  private final FamilyDocumentMapper documentMapper; private final FamilyDocumentVersionMapper versionMapper; private final PhotoDuplicateCandidateMapper duplicateMapper; private final FamilyShareLinkMapper shareMapper; private final FamilyDeviceMapper deviceMapper; private final FamilySyncLogMapper syncMapper;

  public IPage<FamilyDocument> documents(String keyword,String category,long page,long size){ PhotoSpace s=space(); return documentMapper.selectPage(new Page<>(page,Math.min(Math.max(size,1),100)),new LambdaQueryWrapper<FamilyDocument>().eq(FamilyDocument::getSpaceId,s.getId()).eq(FamilyDocument::getDeleted,0).eq(StringUtils.hasText(category),FamilyDocument::getCategory,category).and(StringUtils.hasText(keyword),q->q.like(FamilyDocument::getTitle,keyword).or().like(FamilyDocument::getTags,keyword).or().like(FamilyDocument::getExtractedText,keyword)).orderByDesc(FamilyDocument::getUpdateTime)); }
  public FamilyDocument uploadDocument(MultipartFile file,FamilyRequests.DocumentSave request)throws Exception { if(file==null||file.isEmpty())throw new BusinessException("文档不能为空"); String ext=Optional.ofNullable(file.getOriginalFilename()).orElse("").toLowerCase(Locale.ROOT); if(!(ext.endsWith(".pdf")||ext.endsWith(".docx")||ext.endsWith(".xlsx")||ext.endsWith(".xls")||ext.endsWith(".pptx")||ext.endsWith(".txt")))throw new BusinessException("仅支持 PDF、Office 和 TXT 文档"); SysFile stored=fileService.upload(file,"FAMILY_DOCUMENT"); FamilyDocument d=new FamilyDocument(); d.setSpaceId(space().getId());d.setOwnerId(uid());d.setFileId(stored.getId());d.setTitle(request.title());d.setCategory(request.category());d.setTags(request.tags());d.setVersionNo(1);d.setStatus("PARSING");d.setCreateTime(LocalDateTime.now());d.setUpdateTime(LocalDateTime.now()); documentMapper.insert(d); try { d.setExtractedText(extractor.extract(stored));d.setStatus("READY"); } catch(Exception e){d.setStatus("FAILED");d.setErrorMessage(e.getMessage());} documentMapper.updateById(d); addVersion(d,request.changeNote()); return d; }
  public FamilyDocument updateDocument(Long id,FamilyRequests.DocumentSave r){FamilyDocument d=ownDoc(id);d.setTitle(r.title());d.setCategory(r.category());d.setTags(r.tags());d.setVersionNo(Optional.ofNullable(d.getVersionNo()).orElse(1)+1);d.setUpdateTime(LocalDateTime.now());documentMapper.updateById(d);addVersion(d,r.changeNote());return d;}
  public List<FamilyDocumentVersion> versions(Long id){ownDoc(id);return versionMapper.selectList(new LambdaQueryWrapper<FamilyDocumentVersion>().eq(FamilyDocumentVersion::getDocumentId,id).orderByDesc(FamilyDocumentVersion::getVersionNo));}
  public void deleteDocument(Long id){FamilyDocument d=ownDoc(id);d.setDeleted(1);d.setUpdateTime(LocalDateTime.now());documentMapper.updateById(d);}
  public void writeDocument(Long id,jakarta.servlet.http.HttpServletResponse response,boolean download)throws Exception{FamilyDocument d=ownDoc(id); if(download)fileService.download(d.getFileId(),response);else fileService.preview(d.getFileId(),response);}

  public List<PhotoDuplicateCandidate> scanDuplicates(){PhotoSpace s=space();List<PhotoMedia> media=mediaMapper.selectList(new LambdaQueryWrapper<PhotoMedia>().eq(PhotoMedia::getSpaceId,s.getId()).eq(PhotoMedia::getStatus,1));Map<String,List<PhotoMedia>> byHash=new LinkedHashMap<>();for(PhotoMedia m:media){SysFile f=fileMapper.selectById(m.getOriginalFileId());if(f!=null&&StringUtils.hasText(f.getFileHash()))byHash.computeIfAbsent(f.getFileHash(),k->new ArrayList<>()).add(m);}int count=0;for(List<PhotoMedia> group:byHash.values())if(group.size()>1)for(int i=0;i<group.size();i++)for(int j=i+1;j<group.size();j++){if(duplicateMapper.selectCount(new LambdaQueryWrapper<PhotoDuplicateCandidate>().eq(PhotoDuplicateCandidate::getMediaId,group.get(i).getId()).eq(PhotoDuplicateCandidate::getDuplicateMediaId,group.get(j).getId()))>0)continue;PhotoDuplicateCandidate c=new PhotoDuplicateCandidate();c.setSpaceId(s.getId());c.setMediaId(group.get(i).getId());c.setDuplicateMediaId(group.get(j).getId());c.setMatchType("EXACT");c.setConfidence(BigDecimal.ONE);c.setMarked(1);c.setCreateTime(LocalDateTime.now());duplicateMapper.insert(c);count++;}return duplicateMapper.selectList(new LambdaQueryWrapper<PhotoDuplicateCandidate>().eq(PhotoDuplicateCandidate::getSpaceId,s.getId()).eq(PhotoDuplicateCandidate::getMarked,1).orderByDesc(PhotoDuplicateCandidate::getCreateTime));}
  public List<PhotoDuplicateCandidate> duplicates(){return duplicateMapper.selectList(new LambdaQueryWrapper<PhotoDuplicateCandidate>().eq(PhotoDuplicateCandidate::getSpaceId,space().getId()).eq(PhotoDuplicateCandidate::getMarked,1).orderByDesc(PhotoDuplicateCandidate::getCreateTime));}
  public void markDuplicate(Long id,boolean marked){PhotoDuplicateCandidate c=duplicateMapper.selectById(id);if(c==null||!c.getSpaceId().equals(space().getId()))throw new BusinessException("重复候选不存在");c.setMarked(marked?1:0);duplicateMapper.updateById(c);}

  public FamilyShareLink createShare(FamilyRequests.ShareSave r){FamilyShareLink l=new FamilyShareLink();l.setSpaceId(space().getId());l.setCreatedBy(uid());l.setResourceType(r.resourceType());l.setResourceId(r.resourceId());l.setExpiresAt(r.expiresAt());l.setToken(UUID.randomUUID().toString().replace("-",""));l.setStatus(1);l.setCreateTime(LocalDateTime.now());shareMapper.insert(l);return l;}
  public List<FamilyShareLink> shares(){return shareMapper.selectList(new LambdaQueryWrapper<FamilyShareLink>().eq(FamilyShareLink::getSpaceId,space().getId()).eq(FamilyShareLink::getStatus,1).orderByDesc(FamilyShareLink::getCreateTime));}
  public void revokeShare(Long id){shareMapper.update(null,new com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<FamilyShareLink>().eq(FamilyShareLink::getId,id).eq(FamilyShareLink::getSpaceId,space().getId()).set(FamilyShareLink::getStatus,0));}
  public FamilyShareLink resolveShare(String token){FamilyShareLink l=shareMapper.selectOne(new LambdaQueryWrapper<FamilyShareLink>().eq(FamilyShareLink::getToken,token).eq(FamilyShareLink::getStatus,1));if(l==null||(l.getExpiresAt()!=null&&l.getExpiresAt().isBefore(LocalDateTime.now())))throw new BusinessException("分享链接已失效");return l;}
  public void writeShareContent(String token,jakarta.servlet.http.HttpServletResponse response)throws Exception{FamilyShareLink l=resolveShare(token);if(!"DOCUMENT".equals(l.getResourceType())||l.getResourceId()==null)throw new BusinessException("该分享资源不支持直接预览");FamilyDocument d=documentMapper.selectById(l.getResourceId());if(d==null||d.getDeleted()!=0)throw new BusinessException("分享文档不存在");fileService.preview(d.getFileId(),response);}

  public FamilyDevice registerDevice(FamilyRequests.DeviceSave r){FamilyDevice d=deviceMapper.selectOne(new LambdaQueryWrapper<FamilyDevice>().eq(FamilyDevice::getDeviceKey,r.deviceKey()));if(d==null){d=new FamilyDevice();d.setSpaceId(space().getId());d.setUserId(uid());d.setDeviceKey(r.deviceKey());d.setCreateTime(LocalDateTime.now());d.setStatus(1);deviceMapper.insert(d);}d.setDeviceName(r.deviceName());d.setDeviceType(r.deviceType());d.setLastSeenAt(LocalDateTime.now());d.setUpdateTime(LocalDateTime.now());deviceMapper.updateById(d);return d;}
  public List<FamilyDevice> devices(){return deviceMapper.selectList(new LambdaQueryWrapper<FamilyDevice>().eq(FamilyDevice::getSpaceId,space().getId()).eq(FamilyDevice::getStatus,1).orderByDesc(FamilyDevice::getLastSeenAt));}
  public List<PhotoSpaceMember> members(){return memberMapper.selectList(new LambdaQueryWrapper<PhotoSpaceMember>().eq(PhotoSpaceMember::getSpaceId,space().getId()).eq(PhotoSpaceMember::getStatus,1).orderByAsc(PhotoSpaceMember::getRole));}
  public PhotoSpaceMember saveMember(FamilyRequests.MemberSave r){PhotoSpace s=space();PhotoSpaceMember owner=memberMapper.selectOne(new LambdaQueryWrapper<PhotoSpaceMember>().eq(PhotoSpaceMember::getSpaceId,s.getId()).eq(PhotoSpaceMember::getUserId,uid()).eq(PhotoSpaceMember::getRole,"OWNER").eq(PhotoSpaceMember::getStatus,1));if(owner==null)throw new BusinessException("只有空间所有者可以管理成员");if(!Set.of("MANAGER","CONTRIBUTOR","VIEWER").contains(r.role()))throw new BusinessException("成员角色不合法");PhotoSpaceMember m=memberMapper.selectOne(new LambdaQueryWrapper<PhotoSpaceMember>().eq(PhotoSpaceMember::getSpaceId,s.getId()).eq(PhotoSpaceMember::getUserId,r.userId()));if(m==null){m=new PhotoSpaceMember();m.setSpaceId(s.getId());m.setUserId(r.userId());m.setJoinedAt(LocalDateTime.now());m.setStatus(1);memberMapper.insert(m);}m.setRole(r.role());m.setStatus(1);memberMapper.updateById(m);return m;}
  public void revokeMember(Long userId){PhotoSpace s=space();memberMapper.update(null,new com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<PhotoSpaceMember>().eq(PhotoSpaceMember::getSpaceId,s.getId()).eq(PhotoSpaceMember::getUserId,userId).ne(PhotoSpaceMember::getRole,"OWNER").set(PhotoSpaceMember::getStatus,0));}
  public List<FamilySyncLog> pushSync(Long deviceId,FamilyRequests.SyncPush r){FamilyDevice d=ownDevice(deviceId);d.setSyncCursor(r.cursor());d.setLastSeenAt(LocalDateTime.now());deviceMapper.updateById(d);FamilySyncLog log=new FamilySyncLog();log.setDeviceId(deviceId);log.setDirection("PUSH");log.setEntityType(r.entityType());log.setEntityId(r.entityId());log.setOperation(r.operation());log.setConflictStatus(StringUtils.hasText(r.conflictStatus())?r.conflictStatus():"NONE");log.setMessage(r.message());log.setCreateTime(LocalDateTime.now());syncMapper.insert(log);return syncMapper.selectList(new LambdaQueryWrapper<FamilySyncLog>().eq(FamilySyncLog::getDeviceId,deviceId).orderByDesc(FamilySyncLog::getCreateTime).last("LIMIT 50"));}
  public List<FamilySyncLog> syncLogs(Long deviceId){ownDevice(deviceId);return syncMapper.selectList(new LambdaQueryWrapper<FamilySyncLog>().eq(FamilySyncLog::getDeviceId,deviceId).orderByDesc(FamilySyncLog::getCreateTime).last("LIMIT 100"));}
  private void addVersion(FamilyDocument d,String note){FamilyDocumentVersion v=new FamilyDocumentVersion();v.setDocumentId(d.getId());v.setFileId(d.getFileId());v.setVersionNo(d.getVersionNo());v.setChangeNote(note);v.setCreatedBy(uid());v.setCreateTime(LocalDateTime.now());versionMapper.insert(v);}
  private FamilyDocument ownDoc(Long id){FamilyDocument d=documentMapper.selectOne(new LambdaQueryWrapper<FamilyDocument>().eq(FamilyDocument::getId,id).eq(FamilyDocument::getSpaceId,space().getId()).eq(FamilyDocument::getDeleted,0));if(d==null)throw new BusinessException("家庭文档不存在");return d;}
  private FamilyDevice ownDevice(Long id){FamilyDevice d=deviceMapper.selectOne(new LambdaQueryWrapper<FamilyDevice>().eq(FamilyDevice::getId,id).eq(FamilyDevice::getSpaceId,space().getId()).eq(FamilyDevice::getStatus,1));if(d==null)throw new BusinessException("设备不存在");return d;}
  private PhotoSpace space(){return photoService.getMySpace();} private Long uid(){Long id=SecurityUtils.getUserId();if(id==null)throw new BusinessException("请先登录");return id;}
}
